// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of http.ServeMux.
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	ServeHTTP(w http.ResponseWriter, r *http.Request)
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc("GET "+options.BaseURL+"/healthz", wrapper.Health)
	m.HandleFunc("GET "+options.BaseURL+"/readyz", wrapper.Ready)
	m.HandleFunc("PUT "+options.BaseURL+"/v1/banner", wrapper.UpdateBanner)
	m.HandleFunc("PUT "+options.BaseURL+"/v1/branding", wrapper.UpdateBranding)
	m.HandleFunc("GET "+options.BaseURL+"/v1/config", wrapper.ReadSiteConfig)
	m.HandleFunc("PUT "+options.BaseURL+"/v1/config", wrapper.UpdateSiteConfig)
	m.HandleFunc("GET "+options.BaseURL+"/v1/config/history", wrapper.ReadConfigHistory)
	m.HandleFunc("POST "+options.BaseURL+"/v1/config/history/{revisionId}:restore", wrapper.RestoreConfigRevision)
	m.HandleFunc("PUT "+options.BaseURL+"/v1/footer", wrapper.UpdateFooter)
	m.HandleFunc("PUT "+options.BaseURL+"/v1/home", wrapper.UpdateHome)
	m.HandleFunc("GET "+options.BaseURL+"/v1/home/public", wrapper.ReadPublicHome)
	m.HandleFunc("GET "+options.BaseURL+"/v1/initialization", wrapper.ReadInitializationStatus)
	m.HandleFunc("POST "+options.BaseURL+"/v1/initialization", wrapper.InitializeSite)
	m.HandleFunc("POST "+options.BaseURL+"/v1/initialization:abort", wrapper.AbortInitialization)
	m.HandleFunc("POST "+options.BaseURL+"/v1/initialization:resume", wrapper.ResumeInitialization)
	m.HandleFunc("GET "+options.BaseURL+"/v1/objects/{objectId}", wrapper.ReadConfigObject)
	m.HandleFunc("GET "+options.BaseURL+"/v1/reference-decisions/{sourceOperationId}", wrapper.ReadHomeReferenceDecision)
	m.HandleFunc("GET "+options.BaseURL+"/v1/resource-references", wrapper.ListResourceReferences)
	m.HandleFunc("GET "+options.BaseURL+"/v1/runtime-state", wrapper.ReadRuntimeState)

	return m
}

